import { gsap } from 'gsap';
import { MeshBasicNodeMaterial, MeshStandardNodeMaterial } from 'three/webgpu';
import { uv, vec3, mix, smoothstep, time, uniform, texture, color } from 'three/tsl';

export default function createNode(config, ctx) {
  const { THREE } = ctx;
  const group = new THREE.Group();

  // === CONFIG EXTRACTION ===
  const textItems = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  const colors = config.intent?.visualSpec?.colors ?? {
    background: '#0b0b10',
    surface: '#14141a',
    ink: '#16161d',
    paper: '#e8ecf2',
    accent: '#ff2a38'
  };

  const imageUrl = config.imageUrl ?? '/prism-mock/home/nodes/feature-card.png';

  // === STAGE BACKDROP ===
  const stageGeom = new THREE.PlaneGeometry(7, 6);
  const stageMat = new MeshBasicNodeMaterial({
    color: new THREE.Color(colors.background)
  });
  const stage = new THREE.Mesh(stageGeom, stageMat);
  stage.position.z = -2.5;
  stage.renderOrder = 0;
  group.add(stage);

  // === HEADLINE (pinned at [-1.6, 1.9, 0]) ===
  const headlineText = textItems.find(t => t.role === 'headline' || t.text === 'Inside the atelier');
  const headlineContent = headlineText?.text ?? 'Inside the atelier';
  const headlineMesh = ctx.fontAtlas.createText(headlineContent, {
    fontSize: 68,
    color: colors.paper,
    align: 'left'
  });
  headlineMesh.position.set(-1.6, 1.9, 0);
  headlineMesh.renderOrder = 10;
  group.add(headlineMesh);

  // === PLATE COLUMN SETUP ===
  const plateWidth = 1.9;
  const plateHeight = 1.2;
  const platePitch = 1.5;
  const columnX = 0.9;
  const columnLoopHeight = 9.0;
  const plateCount = 6;

  // Plate caption texts (in order)
  const captions = [
    'DIAL ROOM',
    'ESCAPEMENT BENCH',
    'CNC HALL',
    'FINISHING LAB',
    'ARCHIVE VAULT',
    'ASSEMBLY LINE ONE'
  ];

  const plates = [];
  let texturePromise = Promise.resolve(null);

  // Load base texture once
  texturePromise = ctx.textureLoader.loadTexture(imageUrl).catch(() => null);

  texturePromise.then((baseTex) => {
    // Create 6 plates
    for (let i = 0; i < plateCount; i++) {
      const plateY = i * platePitch;

      // === PLATE CARD (main photograph) ===
      const plateGeom = new THREE.PlaneGeometry(plateWidth, plateHeight);
      const plateMat = new MeshStandardNodeMaterial({
        map: baseTex,
        roughness: 0.6,
        metalness: 0.1,
        clearcoat: 0.1
      });
      const plateMesh = new THREE.Mesh(plateGeom, plateMat);
      plateMesh.position.set(columnX, plateY, 0);
      plateMesh.renderOrder = 5;
      plateMesh.userData.plateIndex = i;
      plateMesh.userData.baseY = plateY;

      // === PLATE BEVEL (frame) ===
      const bevelThickness = 0.03;
      const bevelGeom = new THREE.PlaneGeometry(plateWidth + 2 * bevelThickness, plateHeight + 2 * bevelThickness);
      const bevelMat = new MeshStandardNodeMaterial({
        color: new THREE.Color(colors.ink),
        roughness: 0.5,
        metalness: 0.5
      });
      const bevelMesh = new THREE.Mesh(bevelGeom, bevelMat);
      bevelMesh.position.set(columnX, plateY, -0.01);
      bevelMesh.renderOrder = 4;
      group.add(bevelMesh);

      // === ACCENT STRIP (left edge, emissive red) ===
      const stripWidth = 0.03;
      const stripGeom = new THREE.PlaneGeometry(stripWidth, plateHeight);
      const stripMat = new MeshStandardNodeMaterial({
        color: new THREE.Color(colors.accent),
        emissive: new THREE.Color(colors.accent),
        emissiveIntensity: 1.4,
        metalness: 0.3,
        roughness: 0.4
      });
      const stripMesh = new THREE.Mesh(stripGeom, stripMat);
      stripMesh.position.set(columnX - plateWidth / 2 - stripWidth / 2, plateY, 0.02);
      stripMesh.renderOrder = 6;
      stripMesh.userData.isStrip = true;
      group.add(stripMesh);

      // === PLATE CAPTION (positioned at x=-1.6, fades with focus) ===
      const captionText = captions[i] ?? `PLATE ${i + 1}`;
      const captionMesh = ctx.fontAtlas.createText(captionText, {
        fontSize: 18,
        color: colors.paper,
        align: 'left',
        letterSpacingPx: 1.44 // 0.08em at 18px = ~1.44px
      });
      captionMesh.position.set(-1.6, plateY, 0.1);
      captionMesh.userData.isCaptions = true;
      captionMesh.userData.plateIndex = i;
      captionMesh.userData.baseY = plateY;
      captionMesh.material.opacity = 0;
      captionMesh.material.transparent = true;
      captionMesh.renderOrder = 8;
      group.add(captionMesh);

      group.add(plateMesh);
      plates.push({
        mesh: plateMesh,
        bevel: bevelMesh,
        strip: stripMesh,
        caption: captionMesh
      });
    }
  });

  // === LIGHTING ===
  const keyLight = new THREE.DirectionalLight(0xffffff, 1.2);
  keyLight.position.set(2.5, 2.0, 3.0);
  group.add(keyLight);

  const rimLight = new THREE.DirectionalLight(colors.accent, 0.7);
  rimLight.position.set(-3.0, 1.5, 2.0);
  group.add(rimLight);

  const ambientLight = new THREE.AmbientLight(0xffffff, 0.5);
  group.add(ambientLight);

  // === SCROLL STATE & ANIMATION ===
  const scrollState = {
    targetY: 0,
    currentY: 0,
    velocity: 0,
    damping: 0.12
  };

  let focusedPlateIndex = 0;
  let settleTimeline = null;

  const updatePlateStates = () => {
    plates.forEach((plate, idx) => {
      const baseY = plate.mesh.userData.baseY;
      const worldY = baseY + scrollState.currentY;

      // Looping: wrap position modulo columnLoopHeight
      const loopedY = ((worldY % columnLoopHeight) + columnLoopHeight) % columnLoopHeight;

      // Distance from camera focus line (y=0)
      const distFromFocus = Math.abs(loopedY - (columnLoopHeight / 2));
      const isFocused = distFromFocus < 0.8;

      if (isFocused) {
        focusedPlateIndex = idx;
      }

      // Update positions
      plate.mesh.position.y = baseY + scrollState.currentY;
      plate.bevel.position.y = baseY + scrollState.currentY;
      plate.strip.position.y = baseY + scrollState.currentY;
      plate.caption.position.y = baseY + scrollState.currentY;

      // Focus scale & caption opacity
      if (isFocused) {
        plate.mesh.scale.set(1.06, 1.06, 1.06);
        plate.caption.material.opacity = 1.0;
      } else {
        plate.mesh.scale.set(1.0, 1.0, 1.0);
        plate.caption.material.opacity = 0.4;
      }
    });
  };

  // === SCROLL HANDLER ===
  const onScroll = (e) => {
    const deltaScroll = e.deltaY ?? 0;
    scrollState.velocity = deltaScroll * 0.001 * 1.5; // 1.5 units per viewport scroll
    scrollState.targetY += scrollState.velocity;

    // Kill settle timeline if scrolling
    if (settleTimeline) {
      settleTimeline.kill();
      settleTimeline = null;
    }
  };

  // === ANIMATION LOOP (inertia + settle) ===
  const animationFrame = () => {
    // Apply damping
    scrollState.velocity *= (1 - scrollState.damping);
    scrollState.currentY += scrollState.velocity;

    // If velocity is very small and no settle in progress, start settle
    if (Math.abs(scrollState.velocity) < 0.001 && !settleTimeline) {
      settleTimeline = gsap.timeline();
      settleTimeline.to(scrollState, {
        velocity: 0,
        duration: 0.9,
        ease: 'cubic-bezier(0.165, 0.84, 0.44, 1)'
      });
    }

    updatePlateStates();
    requestAnimationFrame(animationFrame);
  };

  animationFrame();

  // === FLY-THROUGH PRIMITIVE ===
  const flyThroughPrimitive = ctx.primitives['fly-through'](group, {
    depthUnits: 2.5,
    trigger: 'scroll'
  });

  // === CLEANUP ===
  group.userData.handlers = {
    scroll: onScroll
  };

  group.userData.cleanup = () => {
    if (settleTimeline) {
      settleTimeline.kill();
    }
    if (flyThroughPrimitive && flyThroughPrimitive.cleanup) {
      flyThroughPrimitive.cleanup();
    }

    // Dispose geometries & materials
    stageGeom.dispose();
    stageMat.dispose();

    plates.forEach(plate => {
      plate.mesh.geometry.dispose();
      plate.mesh.material.dispose();
      plate.bevel.geometry.dispose();
      plate.bevel.material.dispose();
      plate.strip.geometry.dispose();
      plate.strip.material.dispose();
      plate.caption.geometry?.dispose?.();
      plate.caption.material?.dispose?.();
    });
  };

  return group;
}
